package local.z6panel;

import android.content.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

/** Bounded foreground-only daily catalog, persistent derivatives and shared masters. */
final class WallpaperOnline {
 private static final java.util.concurrent.atomic.AtomicLong REQUESTS=new java.util.concurrent.atomic.AtomicLong(),BYTES=new java.util.concurrent.atomic.AtomicLong();
 private static final ReentrantLock NETWORK=new ReentrantLock(true),CATALOG=new ReentrantLock(true),PREPARE=new ReentrantLock(true);
 private Context owner;private volatile boolean cancelled;private volatile HttpURLConnection connection;
 static String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date());}
 void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 private void check()throws IOException{if(cancelled||Thread.currentThread().isInterrupted()||owner!=null&&(owner.getSharedPreferences("panel",0).getBoolean("wallpaper_publish_hold",false)||!((android.os.PowerManager)owner.getSystemService(Context.POWER_SERVICE)).isInteractive()||!HomeActivity.visible&&!WallpaperActivity.isVisible()))throw new InterruptedIOException();}
 private HttpURLConnection connect(String address)throws IOException{URL u=new URL(address);for(int hop=0;hop<3;hop++){check();if(!"https".equals(u.getProtocol())||!(u.getHost().equals("commons.wikimedia.org")||u.getHost().equals("upload.wikimedia.org")||u.getHost().equals("thumb.wikimedia.org")))throw new IOException("Origen no permitido");REQUESTS.incrementAndGet();HttpURLConnection c=(HttpURLConnection)u.openConnection();connection=c;c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Z6Panel/0.16.0 (personal wallpaper; MediaWiki API)");int code=c.getResponseCode();if(code==200)return c;String location=c.getHeaderField("Location");c.disconnect();if(code>=300&&code<400&&location!=null){u=new URL(u,location);continue;}throw new IOException("Wikimedia no está disponible ("+code+")");}throw new IOException("Demasiadas redirecciones");}
 private JSONObject json(String url)throws Exception{NETWORK.lockInterruptibly();try{check();HttpURLConnection c=connect(url);try(InputStream in=c.getInputStream()){return new JSONObject(new String(WallpaperStore.readLimited(in,1024*1024),"UTF-8"));}finally{c.disconnect();}}finally{NETWORK.unlock();}}
 private void download(String url,File target,int max)throws Exception{NETWORK.lockInterruptibly();boolean success=false;try{check();HttpURLConnection c=connect(url);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(target)){byte[] b=new byte[16384];int n,total=0;while((n=in.read(b))!=-1){check();BYTES.addAndGet(n);total+=n;if(total>max)throw new IOException("Imagen demasiado grande");out.write(b,0,n);}success=true;}finally{c.disconnect();}}finally{NETWORK.unlock();if(!success)target.delete();}}
 private static JSONObject read(File file){try(InputStream in=new android.util.AtomicFile(file).openRead()){return new JSONObject(new String(WallpaperStore.readLimited(in,1024*1024),"UTF-8"));}catch(Exception e){return new JSONObject();}}
 private static File index(Context c){return new File(c.getFilesDir(),"landscape-catalog.json");}
 static JSONObject snapshot(Context c){return read(index(c));}
 static final class Candidate {
  final int id,width,height;final String name,url,asset;final JSONObject page;
  Candidate(JSONObject p)throws Exception{page=p;id=p.getInt("pageid");name=p.optString("title").replaceFirst("^File:","");JSONObject info=p.getJSONArray("imageinfo").getJSONObject(0);width=info.optInt("width");height=info.optInt("height");url=info.optString("thumburl");asset=WallpaperMedia.id("commons:"+id);}
 }
 private static int cap(Context c){return Math.min(1920,WallpaperImages.maximum(c));}
 static boolean sufficient(Context c){WallpaperSource f=file(c);if(f==null)return false;int[] b=f.bounds(),t=WallpaperImages.size(c,cap(c));return b[0]>=t[0]-1&&b[1]>=t[1]-1;}
 private int neededWidth(Context c,JSONObject i){int w=i.optInt("width"),h=i.optInt("height");int[] t=WallpaperImages.size(c,cap(c));if(w<t[0]||h<t[1]||h<=0)return 0;long need=Math.max(t[0],((long)t[1]*w+h-1)/h);for(int step:new int[]{1280,1920,3840})if(need<=step)return step;return 0;}
 private boolean suitable(Context c,JSONObject p){try{JSONObject i=p.getJSONArray("imageinfo").getJSONObject(0),m=i.getJSONObject("extmetadata");String license=value(m,"LicenseShortName");return i.optString("mime").equals("image/jpeg")&&i.optInt("width")>=i.optInt("height")&&neededWidth(c,i)>0&&!i.optString("thumburl").isEmpty()&&!value(m,"Artist").isEmpty()&&(license.startsWith("CC BY")||license.equals("CC0")||license.equals("Public domain"));}catch(Exception e){return false;}}
 private static List<Candidate> candidates(JSONObject catalog)throws Exception{List<Candidate> out=new ArrayList<>();JSONArray items=catalog.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++)out.add(new Candidate(items.getJSONObject(i)));return out;}
 List<Candidate> catalog(Context c)throws Exception{return catalog(c,false);}
 List<Candidate> catalog(Context c,boolean manual)throws Exception{owner=c;CATALOG.lockInterruptibly();try{check();cleanup(c);JSONObject old=snapshot(c);List<Candidate> cached=candidates(old);if(today().equals(old.optString("date"))&&!cached.isEmpty())return cached;SharedPreferences prefs=c.getSharedPreferences("panel",0);long now=System.currentTimeMillis();if(!manual&&now-prefs.getLong("wallpaper_catalog_attempt",0)<3600000){if(!cached.isEmpty())return cached;throw new IOException("Sin catálogo nuevo; usa Reintentar");}prefs.edit().putLong("wallpaper_catalog_attempt",now).apply();Set<Integer> previous=new HashSet<>();for(Candidate item:cached)previous.add(item.id);List<JSONObject> fresh=new ArrayList<>(),repeat=new ArrayList<>();Set<Integer> seen=new HashSet<>();String cursor=old.optString("continue");for(int batch=0;batch<3&&fresh.size()<12;batch++){
  String url="https://commons.wikimedia.org/w/api.php?action=query&generator=categorymembers&gcmtitle=Category%3AFeatured_pictures_of_landscapes&gcmtype=file&gcmnamespace=6&gcmlimit=24&prop=imageinfo&iiprop=url%7Csize%7Cmime%7Cextmetadata&iiextmetadatafilter=Artist%7CLicenseShortName%7CLicenseUrl&iiurlwidth=330&format=json&formatversion=2"+(cursor.isEmpty()?"":"&gcmcontinue="+URLEncoder.encode(cursor,"UTF-8"));JSONObject response=json(url);JSONObject query=response.optJSONObject("query");JSONArray pages=query==null?null:query.optJSONArray("pages");if(pages!=null)for(int n=0;n<pages.length();n++){JSONObject p=pages.getJSONObject(n);int id=p.optInt("pageid");if(seen.add(id)&&suitable(c,p))(previous.contains(id)?repeat:fresh).add(p);}JSONObject continuation=response.optJSONObject("continue");cursor=continuation==null?"":continuation.optString("gcmcontinue");if(cursor.isEmpty()&&batch>0)break;
 }check();for(JSONObject p:repeat)if(fresh.size()<12)fresh.add(p);if(fresh.isEmpty())throw new IOException("No hay paisajes con resolución suficiente");JSONArray items=new JSONArray();for(int i=0;i<Math.min(12,fresh.size());i++)items.put(fresh.get(i));JSONObject result=new JSONObject().put("date",today()).put("continue",cursor).put("items",items);WallpaperStore.writeJson(index(c),result.toString());trimThumbs(c);return candidates(result);
 }catch(Exception failure){List<Candidate> old=candidates(snapshot(c));if(!old.isEmpty()&&!(failure instanceof InterruptedIOException)){return old;}throw failure;}finally{CATALOG.unlock();}}
 static File thumbnailFile(Context c,Candidate item){File dir=new File(c.getFilesDir(),"landscape-thumbnails");dir.mkdirs();return new File(dir,item.id+".jpg");}
 void thumbnail(Context c,Candidate item,File target)throws Exception{owner=c;if(target.isFile()){int[] b=new WallpaperSource(target).bounds();if(b[0]>0&&b[1]>0)return;target.delete();}File raw=File.createTempFile("landscape-thumb-",".tmp",c.getCacheDir());try{download(item.url,raw,512*1024);check();android.graphics.Bitmap b=WallpaperImages.frame(raw,330,186);try{try(OutputStream out=new FileOutputStream(target)){b.compress(android.graphics.Bitmap.CompressFormat.JPEG,78,out);}}finally{b.recycle();}check();trimThumbs(c);}finally{raw.delete();}}
 static void trimThumbs(Context c){File dir=new File(c.getFilesDir(),"landscape-thumbnails");File[] files=dir.listFiles();if(files==null)return;Set<String> keep=new HashSet<>();try{for(Candidate item:candidates(snapshot(c)))keep.add(item.id+".jpg");}catch(Exception ignored){}long bytes=0;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(File f:files)if(!keep.contains(f.getName())||bytes+f.length()>2*WallpaperImages.MB)f.delete();else bytes+=f.length();}
 static int rotation(Context c){int v=c.getSharedPreferences("panel",0).getInt("wallpaper_daily_hours",0);return v==1||v==2||v==3||v==6?v:0;}
 static void rotation(Context c,int hours){c.getSharedPreferences("panel",0).edit().putInt("wallpaper_daily_hours",hours).putLong("wallpaper_daily_epoch",System.currentTimeMillis()).putInt("wallpaper_daily_base",activeIndex(c)).apply();}
 private static int activeIndex(Context c){try{int id=credit(c).optInt("pageid");List<Candidate> list=candidates(snapshot(c));for(int i=0;i<list.size();i++)if(list.get(i).id==id)return i;}catch(Exception ignored){}return 0;}
 static long nextDelay(Context c){int hours=rotation(c);if(hours==0)return -1;long interval=hours*3600000L,elapsed=Math.max(0,System.currentTimeMillis()-c.getSharedPreferences("panel",0).getLong("wallpaper_daily_epoch",System.currentTimeMillis()));return interval-elapsed%interval;}
 private int due(Context c,List<Candidate> items){SharedPreferences p=c.getSharedPreferences("panel",0);int hours=rotation(c),base=p.getInt("wallpaper_daily_base",0);long step=hours==0?0:Math.max(0,System.currentTimeMillis()-p.getLong("wallpaper_daily_epoch",System.currentTimeMillis()))/(hours*3600000L);return (int)Math.floorMod(base+step,items.size());}
 String update(Context c,boolean manual)throws Exception{owner=c;check();if(rotation(c)==0&&today().equals(credit(c).optString("date"))&&file(c)!=null&&sufficient(c))return "El paisaje de hoy ya está guardado";List<Candidate> items=catalog(c,manual);if(!credit(c).optString("date").equals(snapshot(c).optString("date")))c.getSharedPreferences("panel",0).edit().putInt("wallpaper_daily_base",0).putLong("wallpaper_daily_epoch",System.currentTimeMillis()).apply();int start=due(c,items);WallpaperMedia media=new WallpaperMedia(c);for(int n=0;n<items.size();n++){Candidate item=items.get((start+n)%items.size());WallpaperSource existing=media.source(item.asset);if(media.deleted(item.asset)||existing!=null&&!existing.isFile()){if(existing!=null)media.remove(item.asset);continue;}return use(c,item,false);}throw new IOException("Los paisajes disponibles se eliminaron; se conserva el fondo original");}
 String useCandidate(Context c,Candidate item)throws Exception{return use(c,item,true);}
 private String use(Context c,Candidate item,boolean manual)throws Exception{JSONObject meta=prepare(c,item);meta.put("date",snapshot(c).optString("date",today()));check();WallpaperStore.writeJson(new File(new WallpaperStore(c).dir,"daily.json"),meta.toString());SharedPreferences.Editor edit=c.getSharedPreferences("panel",0).edit().putString("wallpaper_daily_date",meta.optString("date"));if(manual){int at=0;for(Candidate candidate:candidates(snapshot(c))){if(candidate.id==item.id)break;at++;}edit.putInt("wallpaper_daily_base",at).putLong("wallpaper_daily_epoch",System.currentTimeMillis());}edit.apply();cleanupKeeping(c,item.asset);return "Paisaje listo · "+meta.optInt("width")+" × "+meta.optInt("height")+" · "+WallpaperImages.bytes(meta.optLong("bytes"));}
 private JSONObject prepare(Context c,Candidate item)throws Exception{owner=c;PREPARE.lockInterruptibly();File raw=null,prepared=null;try{check();WallpaperMedia media=new WallpaperMedia(c);if(media.deleted(item.asset))throw new IOException("Esta imagen se eliminó de Multimedia");WallpaperSource existing=media.source(item.asset);if(existing!=null){if(!existing.isFile()){media.remove(item.asset);throw new IOException("Esta imagen se eliminó de Multimedia");}JSONObject e=media.read().getJSONObject(item.asset);return e.getJSONObject("meta");}WallpaperStore store=new WallpaperStore(c);if(store.dir.getUsableSpace()<15*WallpaperImages.MB)throw new IOException("Falta espacio; se conserva el fondo actual");JSONObject page=item.page;JSONObject info=page.getJSONArray("imageinfo").getJSONObject(0);int required=neededWidth(c,info);if(required==0)throw new IOException("Resolución insuficiente");JSONObject response=json("https://commons.wikimedia.org/w/api.php?action=query&pageids="+item.id+"&prop=imageinfo&iiprop=url%7Csize%7Cmime%7Cextmetadata&iiextmetadatafilter=Artist%7CLicenseShortName%7CLicenseUrl&iiurlwidth="+required+"&format=json&formatversion=2");page=response.getJSONObject("query").getJSONArray("pages").getJSONObject(0);if(!suitable(c,page))throw new IOException("El paisaje dejó de estar disponible");info=page.getJSONArray("imageinfo").getJSONObject(0);raw=File.createTempFile("daily-choice-",".tmp",c.getCacheDir());download(info.getString("thumburl"),raw,5*1024*1024);check();int[] target=WallpaperImages.size(c,cap(c));android.graphics.Bitmap image=WallpaperImages.frame(raw,target[0],target[1]);int w=image.getWidth(),h=image.getHeight();prepared=File.createTempFile("daily-prepared-",".jpg",c.getCacheDir());try{if(w<target[0]-1||h<target[1]-1)throw new IOException("La descarga no alcanza la resolución necesaria");for(int q:new int[]{85,80,75}){try(OutputStream out=new FileOutputStream(prepared)){image.compress(android.graphics.Bitmap.CompressFormat.JPEG,q,out);}if(prepared.length()<=(cap(c)>=1920?2:1)*WallpaperImages.MB)break;}}finally{image.recycle();}if(prepared.length()>(cap(c)>=1920?2:1)*WallpaperImages.MB)throw new IOException("La imagen supera el límite");check();JSONObject m=info.getJSONObject("extmetadata");JSONObject meta=new JSONObject().put("id",item.asset).put("pageid",item.id).put("title",page.optString("title")).put("name",item.name).put("author",value(m,"Artist")).put("license",value(m,"LicenseShortName")).put("licenseUrl",value(m,"LicenseUrl")).put("source",info.optString("descriptionurl")).put("date",snapshot(c).optString("date",today())).put("width",w).put("height",h).put("bytes",prepared.length()).put("origin","landscape");WallpaperSource source=media.publish(prepared,item.asset,WallpaperMedia.DAILY,meta);meta.put("uri",source.uri.toString());media.updateMeta(item.asset,meta);return meta;
 }finally{if(raw!=null)raw.delete();if(prepared!=null)prepared.delete();PREPARE.unlock();}}
 String conserve(Context c,Candidate item)throws Exception{WallpaperStore store=new WallpaperStore(c);if(store.find(item.asset)!=null)return "Ya está conservada en Mis fotos";if(store.photos().size()>=WallpaperStore.MAX_IMAGES)throw new IOException("Biblioteca completa: máximo 50 imágenes");JSONObject meta=prepare(c,item);long bytes=meta.optLong("bytes");for(WallpaperStore.Photo photo:store.photos())bytes+=photo.file.length();if(bytes>WallpaperStore.MAX_LIBRARY)throw new IOException("Biblioteca completa: máximo 100 MB");check();meta.put("conserved",true);new WallpaperMedia(c).updateMeta(item.asset,meta);store.addConserved(meta);return "Conservada en el TV · No se elimina al renovar";}
 void prefetch(Context c)throws Exception{if(rotation(c)==0)return;List<Candidate> items=candidates(snapshot(c));if(items.isEmpty()||!today().equals(snapshot(c).optString("date")))return;Candidate next=items.get((due(c,items)+1)%items.size());if(!new WallpaperMedia(c).deleted(next.asset))prepare(c,next);}
 static String state(Context c,Candidate item){WallpaperMedia media=new WallpaperMedia(c);if(media.deleted(item.asset))return "Eliminada";WallpaperSource source=media.source(item.asset);if(source==null)return "Disponible para descargar";JSONObject e=media.read().optJSONObject(item.asset);if(!source.isFile())return "Eliminada";return e!=null&&WallpaperMedia.SAVED.equals(e.optString("album"))?"Conservado":"Descargado · temporal";}
 static void migrate(Context c){try{WallpaperStore store=new WallpaperStore(c);JSONObject current=credit(c);if(!current.has("uri")){String name=current.optString("file");if(name.matches("daily-[a-f0-9-]+\\.jpg")){File original=new File(store.dir,name);if(original.isFile()){String id=WallpaperMedia.id("legacy:"+name);current.put("id",id).put("bytes",original.length());WallpaperSource shared=new WallpaperMedia(c).publish(original,id,WallpaperMedia.DAILY,current);current.put("uri",shared.uri.toString());WallpaperStore.writeJson(new File(store.dir,"daily.json"),current.toString());new WallpaperMedia(c).updateMeta(id,current);original.delete();}}}}catch(Exception pending){android.util.Log.w("Z6Media","Paisaje pendiente de publicación");}}
 static void cleanup(Context c){cleanupKeeping(c,null);}
 private static void cleanupKeeping(Context c,String explicit){try{WallpaperMedia media=new WallpaperMedia(c);JSONObject all=media.read();Set<String> batch=new HashSet<>();boolean currentBatch=today().equals(snapshot(c).optString("date"));if(currentBatch)for(Candidate item:candidates(snapshot(c)))batch.add(item.asset);String active=explicit!=null?explicit:c.getSharedPreferences("panel",0).getString("wallpaper_mode","original").equals("daily")?credit(c).optString("id"):"";for(Iterator<String> keys=all.keys();keys.hasNext();){String id=keys.next();JSONObject entry=all.getJSONObject(id),meta=entry.optJSONObject("meta");if(entry.optBoolean("deleted")||!WallpaperMedia.DAILY.equals(entry.optString("album"))||meta==null)continue;if(!id.equals(active)&&(!today().equals(meta.optString("date"))||currentBatch&&!batch.contains(id)))media.remove(id);}Set<String> keep=new HashSet<>();keep.add(active);for(Candidate item:candidates(snapshot(c)))keep.add(item.asset);for(WallpaperStore.Photo photo:new WallpaperStore(c).photos())keep.add(photo.id);media.pruneTombstones(keep);trimThumbs(c);}catch(Exception e){android.util.Log.w("Z6Media","Limpieza pendiente");}}
 static void maintain(Context c){if(c.getSharedPreferences("panel",0).getBoolean("wallpaper_publish_hold",false))return;WallpaperStore store=new WallpaperStore(c);store.migrate();migrate(c);try{store.reconcile();}catch(Exception ignored){}cleanup(c);}
 static String value(JSONObject metadata,String key){JSONObject v=metadata.optJSONObject(key);return v==null?"":v.optString("value");}
 static JSONObject credit(Context c){return read(new File(new WallpaperStore(c).dir,"daily.json"));}
 static WallpaperSource file(Context c){JSONObject j=credit(c);String path=j.optString("file");if(!j.has("uri")&&!path.matches("daily-[a-f0-9-]+\\.jpg"))return null;WallpaperSource source=WallpaperMedia.reference(c,j,new File(new WallpaperStore(c).dir,path));return source.isFile()?source:null;}
 static void recordFailure(Context c,int id,String name,Exception e){try{WallpaperStore.writeJson(new File(c.getFilesDir(),"landscape-last-error.json"),new JSONObject().put("time",System.currentTimeMillis()).put("id",id).put("name",name).put("error",e.toString()).toString());}catch(Exception ignored){}}
 static JSONObject inspect(Context c)throws Exception{JSONObject state=snapshot(c);JSONArray items=state.optJSONArray("items");File[] files=new File(c.getFilesDir(),"landscape-thumbnails").listFiles();long bytes=0;int count=0;if(files!=null)for(File f:files)if(f.isFile()){bytes+=f.length();count++;}JSONArray shared=new JSONArray();JSONObject entries=new WallpaperMedia(c).read();for(Iterator<String> it=entries.keys();it.hasNext();){String id=it.next();JSONObject e=entries.getJSONObject(id);shared.put(new JSONObject().put("id",id).put("uri",e.optString("uri")).put("album",e.optString("album")).put("committed",e.optBoolean("committed")).put("deleted",e.optBoolean("deleted")).put("bytes",e.optLong("bytes")));}return new JSONObject().put("date",state.optString("date")).put("count",items==null?0:items.length()).put("thumbnailCount",count).put("thumbnailBytes",bytes).put("networkRequests",REQUESTS.get()).put("downloadBytes",BYTES.get()).put("rotationHours",rotation(c)).put("shared",shared);}
 static JSONObject lastFailure(Context c){return read(new File(c.getFilesDir(),"landscape-last-error.json"));}
}
